∀ {k : ℕ} {W : ℝ → Breakdown.Space → Breakdown.Space} {b : Fin k → ℝ → Breakdown.Space → Breakdown.Space}
  {κ : Fin k → ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space} {g F : ℝ → Breakdown.Space → Breakdown.Space}
  (c : ℝ),
  Breakdown.IsRightSide W (fun i σ y => c • b i σ y) κ v G g F → Breakdown.IsRightSide W b (fun i => c * κ i) v G g F

∀ {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {D : ℝ},
  Breakdown.CoerciveWeak.IsWeakSecondDerivState W HW D → ∀ (σ : ℝ), LipschitzWith D.toNNReal (fderiv ℝ (W σ))

∀ {u W₀ : Breakdown.Space → Breakdown.Space}
  {H : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {D : ℝ},
  Breakdown.CoerciveWeak.EnergyIdentityWeakInternal.WeakSliceData u W₀ H D → 0 ≤ D

∀ {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {D : ℝ},
  Breakdown.CoerciveWeak.IsWeakSecondDerivState W HW D → ∀ (s : ℝ) (y : Breakdown.Space), ‖fderiv ℝ (W s) y‖ ≤ D

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {w₀ epsSup epsGradSup ratio : ℝ},
  Breakdown.CoerciveWeak.IsAdmissibleWeak m P h w W HW w₀ epsSup epsGradSup ratio →
    ∀ (β : Fin nE) (ι : ℤ × ℤ) (y : Breakdown.Space),
      |Breakdown.CoerciveWeak.Internal.WeakPairingSplit.epsWeight m β ι y| ≤ epsSup

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : NormedSpace ℝ X] {F : ℝ × Breakdown.Space → X} {s : ℝ}
  {y : Breakdown.Space},
  DifferentiableAt ℝ F (s, y) → ∀ (e : Breakdown.Space), (fderiv ℝ (fun u => F (s, u)) y) e = (fderiv ℝ F (s, y)) (0, e)

∀ {β : Type u_2} {γ : Type u_3} [inst : MeasurableSpace β] [inst_1 : MeasurableSpace γ] {ν : MeasureTheory.Measure β}
  {ρ : MeasureTheory.Measure γ} [MeasureTheory.SFinite ρ] {g : β → γ → ENNReal},
  AEMeasurable (fun z => g z.1 z.2) (ν.prod ρ) → ∀ᵐ (s : β) ∂ν, AEMeasurable (g s) ρ

∀ {β : Type u_2} {γ : Type u_3} [inst : MeasurableSpace β] [inst_1 : MeasurableSpace γ] {ν : MeasureTheory.Measure β}
  {ρ : MeasureTheory.Measure γ} [MeasureTheory.SFinite ρ] {g : β → γ → ℝ},
  AEMeasurable (fun z => g z.1 z.2) (ν.prod ρ) → ∀ᵐ (s : β) ∂ν, AEMeasurable (g s) ρ

∀ {u : ↥Breakdown.Cert.XX} {v : Breakdown.Cert.VelField} {G : Breakdown.Cert.GradField}
  {H : Breakdown.Cert.SecondField},
  Breakdown.Cert.IsReadingOf u v G H → (Breakdown.periodLIntegral fun σ y => Breakdown.matSq (G σ y)) < ⊤

∀ {W : ℝ → Breakdown.Space → Breakdown.Space}
