  Breakdown.CoerciveWeak.IsWeakSecondDerivState W HW D → 0 ≤ D

∀ {k p : ℕ} (L : (Fin (k + 1) → ℕ) → ℕ),
  Breakdown.GridSimplex.boundaryDoorSet L =
    {s ∈ Breakdown.GridSimplex.doorSet L | Breakdown.GridSimplex.OnBoundary s.1 s.2.1 s.2.2}

∀ {u : ↥Breakdown.Cert.XX} {v : Breakdown.Cert.VelField} {G : Breakdown.Cert.GradField}
  {H : Breakdown.Cert.SecondField},
  Breakdown.Cert.IsReadingOf u v G H → ∀ᵐ (σ : ℝ), ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (‖v σ y‖ ^ 6) < ⊤

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {w₀ epsSup epsGradSup ratio : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.CoerciveWeak.IsAdmissibleWeak m P h w W HW w₀ epsSup epsGradSup ratio →
    Breakdown.Coercive.IsSmoothPerturbation P v → ∀ (β : Fin nE), ∀ ι ∈ (m.epsP β).modes, -ι ∉ (m.epsP β).modes

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {w₀ epsSup epsGradSup ratio : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.SmoothPerturbationIsPerturbationHolds →
    Breakdown.CoerciveWeak.IsAdmissibleWeak m P h w W HW w₀ epsSup epsGradSup ratio →
      Breakdown.Coercive.IsSmoothPerturbation P v →
        ∀ (β : Fin nE),
          AEMeasurable (fun z => Breakdown.Coercive.Internal.SmoothPieceEpsCore.posSeries m P v β z.1 z.2)
            Breakdown.Coercive.Internal.PieceAbsorb.slabMeasure

∀ {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {D : ℝ},
  Breakdown.CoerciveWeak.IsWeakSecondDerivState W HW D → ∀ (σ : ℝ) (y : Breakdown.Space), ‖HW σ y‖ * (1 + ‖y‖) ≤ |D|

∀ {k : ℕ} {W : ℝ → Breakdown.Space → Breakdown.Space} {act : Fin k → ℝ → Breakdown.Space → Breakdown.Space}
  (κ : Fin k → ℝ) {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space} (z : ℝ × Breakdown.Space),
  g z.1 z.2 + (G z.1 z.2) (W z.1 z.2) + (fderiv ℝ (W z.1) z.2) (v z.1 z.2) + ∑ i, κ i • act i z.1 z.2 =
    g z.1 z.2 - Breakdown.secondDerivTrace (H z.1 z.2) + (G z.1 z.2) (W z.1 z.2) + (fderiv ℝ (W z.1) z.2) (v z.1 z.2) +
        ∑ i, κ i • act i z.1 z.2 +
      Breakdown.secondDerivTrace (H z.1 z.2)

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
