  Breakdown.CoerciveWeak.IsAdmissibleWeak m P h w W HW w₀ epsSup epsGradSup ratio →
    ∀ (β : Fin nE) (ι : ℤ × ℤ), Measurable (Breakdown.CoerciveWeak.Internal.WeakPairingSplit.epsWeight m β ι)

