  Breakdown.CoerciveWeak.EnergyIdentityWeakInternal.WeakSliceData u W₀ H D → ∀ (y : Breakdown.Space), ‖W₀ y‖ ≤ D

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : NormedSpace ℝ X] {F : ℝ × Breakdown.Space → X} {s : ℝ}
